def transform(grid):
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    centers=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if grid[r][c]==0 and grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    for r,c in centers:
        for rr,cc in centers:
            if (r,c)<(rr,cc):
                if r==rr and cc-c>2:
                    for x in range(c+2,cc-1): out[r][x]=1
                if c==cc and rr-r>2:
                    for x in range(r+2,rr-1): out[x][c]=1
    return out
